const fs = require('node:fs');
const path = require('node:path');

// WeChat's module loader only loads JavaScript, not JSON via require().
// Keep the original evidence intact and generate a runtime module from it.
const fixtureDir = path.resolve(__dirname, '../miniprogram/fixtures');
for (const sample of ['daily1-v2', 'flower1-v2']) {
  const original = fs.readFileSync(path.join(fixtureDir, `${sample}.json`), 'utf8');
  JSON.parse(original); // Refuse to emit an invalid fixture.
  fs.writeFileSync(path.join(fixtureDir, `${sample}.js`),
    '// Generated by scripts/prepare-demo.cjs; edit the JSON source, then regenerate.\nmodule.exports = ' + original.trim() + ';\n');
}
